-- Migration: 0212_atoms_title_kind
-- Description: Provenance of `atoms.title` (0097) — was it generated by the
--   LLM, or is it the deterministic [`fallback_title`] opening-sentence
--   headline?
--
--   Why this exists (title-always-present PR, 2026-09-09). The founder's
--   requirement is a title IMMEDIATELY, with no dependence on the async LLM
--   sweep having run — so `routes::ingest` now writes a deterministic
--   fallback title SYNCHRONOUSLY at insert time, and the sweep's job is to
--   come back later and try to upgrade it to a real LLM headline. Before this
--   column, the sweep's only candidate predicate was `title IS NULL` — once
--   ingest always sets a title, every atom would satisfy that on its very
--   first read and the sweep would never touch it again, permanently
--   freezing every coral on its ingest-time fallback title. `title_kind`
--   gives the sweep a second thing to select on: `title IS NULL OR
--   title_kind = 'fallback'`.
--
--   Two values, both lowercase to match `atoms.source_type`/`scope`'s
--   existing free-text convention rather than a Postgres ENUM (adding a
--   third value later would need a type migration on top of a column one):
--     'llm'      — `services::atom_title::generate_title` got a usable
--                  completion back from the model.
--     'fallback' — no LLM configured, the account's egress policy forbade the
--                  call, the model returned the `none` sentinel or a banned
--                  preamble shape, or `routes::ingest`'s synchronous write ran
--                  before the sweep ever reached this atom.
--
--   NULL is the THIRD state: every atom titled before this column existed
--   (including every fallback title `atom_title_backfill` wrote prior to this
--   PR) has no recorded kind. It is NOT treated identically to `'fallback'`
--   by the sweep's candidate predicate — `(title IS NULL OR title_kind =
--   'fallback')` is false for a `title SET, title_kind NULL` row, proven by
--   truth table on PG16 (title-always-present PR, independent review finding
--   M1). Left alone, every legacy fallback-titled row would stay frozen on
--   its pre-column title forever, exactly the freeze this column exists to
--   prevent. The one-shot backfill below closes that gap by actually
--   normalizing every such row to `'fallback'` at migration time, rather than
--   widening the predicate to re-derive "NULL means fallback" on every read
--   forever — a single UPDATE, once, is cheaper than a permanently more
--   complex hot-path predicate, and leaves exactly two states
--   (`'llm'`/`'fallback'`) for every titled row from this point on.
--
--   Idempotent and safe to run on a DB that has never had a NULL-kind titled
--   row (a fresh tenant, or one that already went through this backfill): the
--   `WHERE` clause matches nothing and the `UPDATE` is a no-op.
--
--   Partial index on the 'fallback' value only: the sweep's widened candidate
--   query filters on it directly, and a full-column index would waste space
--   indexing 'llm' rows the query never selects by this column alone (it
--   still needs the `title IS NULL` half of the OR, which has no index of its
--   own — see 0097's note that titles are always read alongside a
--   `timestamp`-scanned window, never searched standalone). Cheap: `WHERE
--   title_kind = 'fallback'` is exactly the sweep's own predicate half, so
--   the index only ever grows to the size of the sweep's own remaining
--   backlog, never the whole table.
--
--   Paired with `migrations_tenant/0080_atoms_title_kind.sql`. `atoms` is one
--   of the shared content tables — a column added to only one tree fails
--   `scripts/check_schema_parity.sh` by design.

ALTER TABLE atoms ADD COLUMN IF NOT EXISTS title_kind TEXT;

COMMENT ON COLUMN atoms.title_kind IS
    'Provenance of atoms.title: ''llm'' (the model produced it) or '
    '''fallback'' (routes::ingest''s synchronous write, or '
    'services::atom_title::fallback_title via the sweep — no LLM configured, '
    'egress-blocked, or the model''s output was rejected). NULL is a legacy '
    'row titled before this column existed; the one-shot backfill below '
    'normalizes it to ''fallback'' at migration time so it is not silently '
    'excluded from the sweep''s candidate predicate.';

CREATE INDEX IF NOT EXISTS idx_atoms_title_kind_fallback
    ON atoms (title_kind)
    WHERE title_kind = 'fallback';

-- One-shot backfill (independent review finding M1): every row titled before
-- this column existed has `title IS NOT NULL AND title_kind IS NULL`. The
-- sweep's candidate predicate is `(title IS NULL OR title_kind = 'fallback')`
-- — that is FALSE for exactly this shape, so without this statement every
-- legacy fallback-titled row is silently excluded from ever being selected
-- and stays frozen on its pre-column title forever, never getting the LLM
-- upgrade this column exists to offer. Normalizing every such row to
-- `'fallback'` here (once, at migration apply time) makes it a real
-- candidate going forward, through the SAME predicate every other
-- fallback-titled row already relies on — no predicate widening needed.
-- Idempotent: a second application (or a DB with no such rows) matches
-- nothing and updates zero rows.
UPDATE atoms
SET    title_kind = 'fallback'
WHERE  title IS NOT NULL
  AND  title_kind IS NULL;
